package ec.edu.unl.sec.shared.api;import static org.assertj.core.api.Assertions.*;import org.junit.jupiter.api.Test;class EntityTagSupportTest{@Test void rendersAndParsesStrongTag(){assertThat(EntityTagSupport.strong(7)).isEqualTo("\"7\"");assertThat(EntityTagSupport.require("\"7\"")).isEqualTo(7);}@Test void mapsMissingAndStalePreconditions(){assertThatThrownBy(()->EntityTagSupport.require(null)).isInstanceOf(DomainProblemException.class).extracting("code").isEqualTo("PRECONDITION_REQUIRED");assertThatThrownBy(()->EntityTagSupport.verify("\"2\"",3)).isInstanceOf(DomainProblemException.class).extracting("code").isEqualTo("STALE_DRAFT");}}
